import{_ as o,l,o as e,c as s,v as t,p as n,x as r,d,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const b=JSON.parse('{"title":"格与 LWE 直觉","description":"","frontmatter":{"title":"格与 LWE 直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/lattice-lwe.md","filePath":"cs/lattice-lwe.md","lastUpdated":1789023840000}'),p={name:"cs/lattice-lwe.md"};function h(_,a,m,L,u,A){const i=l("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="格与-lwe-直觉" tabindex="-1">格与 LWE 直觉 <a class="header-anchor" href="#格与-lwe-直觉" aria-label="Permalink to &quot;格与 LWE 直觉&quot;">​</a></h1><div class="epigraph"><p>格是 $\\mathbb{R}^n$ 中的离散子群。短向量难；带误差的线性方程（LWE）平均难，且可从最坏格问题归约——后量子候选停在这一不对称上。</p><footer>—— 据 Micciancio and Goldwasser；Regev, On Lattices, Learning with Errors, 2005, 2009 整理</footer></div><p>上一课<a href="/cs/elliptic-curve-group">椭圆曲线</a> 的 DLP 被 Shor 打穿。缺口是<strong>格</strong>：\\(\\Lambda=B\\mathbb{Z}^n\\)。SVP、CVP 最坏难（某些近似因子下 NP-hard）。Regev 的 LWE：给 \\((A, As+e \\bmod q)\\)，\\(e\\) 小噪声，求 \\(s\\)。平均实例可证至少与最坏格一样难。本课直觉，不写 Kyber 参数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>好基（近正交）上 SVP 易；坏基（约化差）上同一格难。公钥是坏基，私钥是好基——这是 Ajtai、GGH 的老图像，实现要防攻击。LWE 把「噪声线性代数」当 OWF 形状：无噪声则高斯消元；有噪声则统计上像均匀（对合适参数）。<a href="/cs/one-way-functions-avg">OWF 课</a> 点名过最坏到平均；本课落地。</p><p>不要把 LWE 写成机器学习课：这里的误差是为困难而加，不是拟合数据。</p><h3 id="不是-rsa-的模" tabindex="-1">不是 RSA 的模 \\(n\\) <a class="header-anchor" href="#不是-rsa-的模" aria-label="Permalink to &quot;不是 RSA 的模 $n$&quot;">​</a></h3><p>模 \\(q\\) 是小整数（万到万千），维 \\(n\\) 几百。困难来自高维噪声，不是大整数分解。</p><p><span class="marginnote">Regev 2005/2009。Micciancio–Regev 综述。Ajtai 1996 最坏到平均。NIST 后量子：Kyber/Dilithium 基于 MLWE/Module，本课不替代规格书。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画二维格的短向量 vs 长基。写 LWE 样本形状。对照 QR / DLP：量子算法对 LWE 无已知多项式解（Shor 不适用）。指出：参数选错（噪声太小/太大）会易解或解密失败。</p>',11)),(e(),n(E,null,{default:r(()=>[c(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20LAT%5B%22%E6%A0%BC%20%CE%9B%22%5D%20--%3E%20SVP%5B%22%E7%9F%AD%E5%90%91%E9%87%8F%E6%9C%80%E5%9D%8F%E9%9A%BE%22%5D%0A%20%20SVP%20--%3E%20LWE%5B%22LWE%20%E5%B9%B3%E5%9D%87%E9%9A%BE%22%5D%0A%20%20LWE%20--%3E%20PQC%5B%22%E5%90%8E%E9%87%8F%E5%AD%90%E5%8E%9F%E8%AF%AD%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>数论单元结束：从同余到域、DLP、素性、ECC，最后格。逻辑单元下一课起不再用 LWE。密码学主干协议仍可用 ECC；本补层只把「量子之后的候选困难」钉在格上。</p><p>SIS（短整数解）是对偶图像，点名。</p><p>SIS：已知 \\(A\\)，求短 \\(e\\neq 0\\) 使 \\(Ae=0\\bmod q\\)。LWE 是「带噪声的求逆」。环/模 LWE 用多项式环降公钥体积，也引入代数结构攻击，参数要谨慎。与 QR、DLP 分工：量子算法目前没有 Shor 式的周期发现可套。数论单元到此结束。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不证 Regev 归约，不引入理想格环上的攻击。不把区块链当应用。后课默认：LWE 是带噪线性方程的平均困难，来自格。下一单元命题逻辑与 CNF。</p><p>短向量几何难；LWE 把难改写成带噪线性方程的平均情形，并有最坏到平均归约。模数小、维数高，与 RSA 大整数不是一类。数论补层到此交给逻辑。</p><p>上一课留下的缺口在本课收口；「格与 LWE 直觉」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>格上短向量难；坏基藏几何。</li><li>LWE：噪声破坏消元，平均 \\(\\leftarrow\\) 最坏。</li><li>Shor 不直接打穿；参数敏感。</li><li>出处：Ajtai；Regev, 2005/2009；Micciancio and Goldwasser。</li></ul>',10))])}const f=o(p,[["render",h]]);export{b as __pageData,f as default};
